precision highp float;
precision highp int;
#define HLSLCC_ENABLE_UNIFORM_BUFFERS 1
#if HLSLCC_ENABLE_UNIFORM_BUFFERS
#define UNITY_UNIFORM
#else
#define UNITY_UNIFORM uniform
#endif
#define UNITY_SUPPORTS_UNIFORM_LOCATION 0
#if UNITY_SUPPORTS_UNIFORM_LOCATION
#define UNITY_LOCATION(x) layout(location = x)
#define UNITY_BINDING(x) layout(binding = x, std140)
#else
#define UNITY_LOCATION(x)
#define UNITY_BINDING(x) layout(std140)
#endif
uniform 	float _Intensity;
uniform 	float _InvertColor;
uniform 	float _HueR;
uniform 	mediump float _UIColorCtrl;
uniform 	vec4 _Color1;
uniform 	vec4 _MainTex_ST;
uniform 	vec4 _ParticleTex_ST;
uniform 	float _Saturation;
uniform 	float _Lightness;
UNITY_LOCATION(0) uniform mediump sampler2D _MainTex;
UNITY_LOCATION(1) uniform mediump sampler2D _ParticleTex;
in mediump vec4 vs_COLOR0;
in mediump vec2 vs_TEXCOORD0;
layout(location = 0) out mediump vec4 SV_Target0;
vec4 u_xlat0;
vec4 u_xlat1;
bool u_xlatb1;
vec4 u_xlat2;
mediump vec4 u_xlat16_2;
vec4 u_xlat3;
mediump vec4 u_xlat16_3;
bool u_xlatb3;
vec4 u_xlat4;
vec3 u_xlat5;
float u_xlat6;
float u_xlat10;
bool u_xlatb15;
void main()
{
    u_xlat0.z = float(-1.0);
    u_xlat0.w = float(0.666666687);
    u_xlat1.z = float(1.0);
    u_xlat1.w = float(-1.0);
    u_xlat2.xy = vs_TEXCOORD0.xy * _MainTex_ST.xy + _MainTex_ST.zw;
    u_xlat16_2 = texture(_MainTex, u_xlat2.xy);
    u_xlat3.xy = vs_TEXCOORD0.xy * _ParticleTex_ST.xy + _ParticleTex_ST.zw;
    u_xlat16_3 = texture(_ParticleTex, u_xlat3.xy);
    u_xlat4.xyw = u_xlat16_2.yzx * u_xlat16_3.yzx;
    u_xlat0.xy = u_xlat4.yx;
    u_xlat1.xy = u_xlat16_2.yz * u_xlat16_3.yz + (-u_xlat0.xy);
    u_xlat2.x = u_xlat16_2.w * vs_COLOR0.w;
    u_xlat2.w = u_xlat16_3.w * u_xlat2.x;
    u_xlatb3 = u_xlat0.y>=u_xlat4.y;
    u_xlat3.x = u_xlatb3 ? 1.0 : float(0.0);
    u_xlat0 = u_xlat3.xxxx * u_xlat1 + u_xlat0;
    u_xlat4.xyz = u_xlat0.xyw;
    u_xlatb1 = u_xlat4.w>=u_xlat4.x;
    u_xlat1.x = u_xlatb1 ? 1.0 : float(0.0);
    u_xlat0.xyw = u_xlat4.wyx;
    u_xlat0 = u_xlat0 + (-u_xlat4);
    u_xlat0 = u_xlat1.xxxx * u_xlat0 + u_xlat4;
    u_xlat1.x = min(u_xlat0.y, u_xlat0.w);
    u_xlat1.x = u_xlat0.x + (-u_xlat1.x);
    u_xlat6 = u_xlat1.x * 6.0 + 1.00000001e-10;
    u_xlat5.x = (-u_xlat0.y) + u_xlat0.w;
    u_xlat5.x = u_xlat5.x / u_xlat6;
    u_xlat5.x = u_xlat5.x + u_xlat0.z;
    u_xlat5.xyz = abs(u_xlat5.xxx) + vec3(1.0, 0.666666687, 0.333333343);
    u_xlat5.xyz = fract(u_xlat5.xyz);
    u_xlat5.xyz = u_xlat5.xyz * vec3(6.0, 6.0, 6.0) + vec3(-3.0, -3.0, -3.0);
    u_xlat5.xyz = abs(u_xlat5.xyz) + vec3(-1.0, -1.0, -1.0);
    u_xlat5.xyz = clamp(u_xlat5.xyz, 0.0, 1.0);
    u_xlat5.xyz = u_xlat5.xyz + vec3(-1.0, -1.0, -1.0);
    u_xlat6 = u_xlat0.x + 1.00000001e-10;
    u_xlat1.x = u_xlat1.x / u_xlat6;
    u_xlat6 = vs_COLOR0.y * 2.0 + (-_Saturation);
    u_xlat6 = _UIColorCtrl * u_xlat6 + _Saturation;
    u_xlat1.x = u_xlat6 * u_xlat1.x;
    u_xlat5.xyz = u_xlat1.xxx * u_xlat5.xyz + vec3(1.0, 1.0, 1.0);
    u_xlat1.x = vs_COLOR0.z + -0.5;
    u_xlat1.x = u_xlat1.x * 2.0 + (-_Lightness);
    u_xlat1.x = _UIColorCtrl * u_xlat1.x + _Lightness;
    u_xlat0.x = u_xlat0.x + u_xlat1.x;
    u_xlat0.xyz = u_xlat5.xyz * u_xlat0.xxx;
    u_xlat0.xyz = u_xlat0.xyz * _Color1.xyz;
    u_xlat1.xyz = (-vs_COLOR0.xyz) + vec3(1.0, 1.0, 1.0);
    u_xlat1.xyz = vec3(_UIColorCtrl) * u_xlat1.xyz + vs_COLOR0.xyz;
    u_xlat3.xyw = u_xlat0.yzx * u_xlat1.yzx;
    u_xlat4.xy = u_xlat3.yx;
    u_xlat0.xy = u_xlat0.yz * u_xlat1.yz + (-u_xlat4.xy);
    u_xlatb1 = u_xlat4.y>=u_xlat3.y;
    u_xlat1.x = u_xlatb1 ? 1.0 : float(0.0);
    u_xlat4.z = float(-1.0);
    u_xlat4.w = float(0.666666687);
    u_xlat0.z = float(1.0);
    u_xlat0.w = float(-1.0);
    u_xlat0 = u_xlat1.xxxx * u_xlat0 + u_xlat4;
    u_xlatb1 = u_xlat3.w>=u_xlat0.x;
    u_xlat1.x = u_xlatb1 ? 1.0 : float(0.0);
    u_xlat3.xyz = u_xlat0.xyw;
    u_xlat0.xyw = u_xlat3.wyx;
    u_xlat0 = (-u_xlat3) + u_xlat0;
    u_xlat0 = u_xlat1.xxxx * u_xlat0 + u_xlat3;
    u_xlat1.x = min(u_xlat0.y, u_xlat0.w);
    u_xlat1.x = u_xlat0.x + (-u_xlat1.x);
    u_xlat6 = u_xlat1.x * 6.0 + 1.00000001e-10;
    u_xlat5.x = (-u_xlat0.y) + u_xlat0.w;
    u_xlat5.x = u_xlat5.x / u_xlat6;
    u_xlat5.x = u_xlat5.x + u_xlat0.z;
    u_xlat10 = vs_COLOR0.x + (-_HueR);
    u_xlat10 = _UIColorCtrl * u_xlat10 + _HueR;
    u_xlat5.x = abs(u_xlat5.x) + u_xlat10;
    u_xlat5.xyz = u_xlat5.xxx + vec3(1.0, 0.666666687, 0.333333343);
    u_xlat5.xyz = fract(u_xlat5.xyz);
    u_xlat5.xyz = u_xlat5.xyz * vec3(6.0, 6.0, 6.0) + vec3(-3.0, -3.0, -3.0);
    u_xlat5.xyz = abs(u_xlat5.xyz) + vec3(-1.0, -1.0, -1.0);
    u_xlat5.xyz = clamp(u_xlat5.xyz, 0.0, 1.0);
    u_xlat5.xyz = u_xlat5.xyz + vec3(-1.0, -1.0, -1.0);
    u_xlat6 = u_xlat0.x + 1.00000001e-10;
    u_xlat1.x = u_xlat1.x / u_xlat6;
    u_xlat5.xyz = u_xlat1.xxx * u_xlat5.xyz + vec3(1.0, 1.0, 1.0);
    u_xlat1.xyz = u_xlat5.xyz * u_xlat0.xxx;
    u_xlat0.xyz = (-u_xlat0.xxx) * u_xlat5.xyz + vec3(1.0, 1.0, 1.0);
    u_xlatb15 = vec4(0.0, 0.0, 0.0, 0.0)!=vec4(_InvertColor);
    u_xlat2.xyz = (bool(u_xlatb15)) ? u_xlat0.xyz : u_xlat1.xyz;
    u_xlat0 = u_xlat2 * vec4(_Intensity);
    SV_Target0 = u_xlat0;
    return;
}

