UNITY_LOCATION(1) uniform mediump sampler2D _DisturbMask;
UNITY_LOCATION(2) uniform mediump sampler2D _MainTex;
UNITY_LOCATION(3) uniform mediump sampler2D _ParticleTex;
UNITY_LOCATION(4) uniform mediump sampler2D _DissolveMask;
